# Cumulative clan XP thresholds for levels 1 through 51.
# https://clashofclans.fandom.com/wiki/Clan_Perks#Clan_XP_Chart
CLAN_XP_CUMULATIVE = [0, 500, 1700, 3600, 6700, 10500, 15000, 20200, 26100, 34000, 42600, 51900, 61900, 72600, 88300, 104700, 121800, 139600, 158100, 181600, 205800, 230700, 256300, 282600, 313900, 345900, 378600, 412000, 446100, 485200, 525000, 565500, 606700, 648600, 695500, 743100, 791400, 840400, 890100, 944800, 1000200, 1056300, 1113100, 1170600, 1233100, 1296300, 1360200, 1424800, 1490100, 1560400, 1631400]

def merge_observations(first, second, daily=False):
    """Merge dated observations; importing an older backup never drops new data."""
    records = {}
    for value in list(first or []) + list(second or []):
        if not isinstance(value, dict) or not api_time(value.get('at')):
            continue
        key = (api_time(value['at'])[:10] + ':' + str(value.get('clanLevel'))) if daily else api_time(value['at'])
        old = records.get(key)
        if not old or api_time(value['at']) >= api_time(old['at']):
            records[key] = copy.deepcopy(value)
    return sorted(records.values(), key=lambda v: api_time(v['at']))


def army_progress(profile):
    """Level completion for permanent Home Village armies, relative to this TH.

    Every eligible level has equal weight, including level 1/unlocking. Equipment
    uses owned pieces only and is excluded from the combined army percentage.
    Missing response collections remain unknown rather than becoming zero.
    """
    th = profile.get('townHallLevel')
    result = {'townHall': th, 'at': api_time(profile.get('profileCheckedAt')),
              'percent': None, 'groups': {}, 'issues': []}
    if not integer(th) or not 1 <= th <= PROGRESSION_CAPS['maxTownHall']:
        result['issues'].append('This Town Hall is outside the bundled cap table.')
        return result
    canon = lambda name: re.sub(r'[^a-z0-9]', '', str(name).casefold())
    ignored = {canon(v) for v in PROGRESSION_CAPS['ignored']}
    known = {canon(v['name']) for v in PROGRESSION_CAPS['units']}
    sources = {'troops': [], 'spells': [], 'heroes': [], 'pets': [], 'siege': [], 'equipment': []}
    raw = {}
    for field in ('troops', 'spells', 'heroes', 'pets', 'heroEquipment'):
        raw[field] = [v for v in profile.get(field, []) if isinstance(v, dict) and v.get('village', 'home') == 'home'] if isinstance(profile.get(field), list) else []
    lookup = {canon(v.get('name')): v for field in raw for v in raw[field]}
    unknown = sorted({str(v.get('name')) for field in ('troops', 'spells', 'heroes', 'pets') for v in raw[field]
                      if canon(v.get('name')) not in known | ignored})
    unsupported_fields = {field for field in raw if any(canon(v.get('name')) not in known | ignored for v in raw[field])}
    if unknown:
        result['issues'].append('Cap table needs an update for: ' + ', '.join(unknown))
    fields = {'troops': 'troops', 'siege': 'troops', 'spells': 'spells', 'heroes': 'heroes', 'pets': 'troops', 'equipment': 'heroEquipment'}
    for unit in PROGRESSION_CAPS['units']:
        maximum = unit['caps'][th - 1]
        if not maximum:
            continue
        group = unit['group']
        item = lookup.get(canon(unit['name']))
        if group == 'equipment' and not item:
            continue
        level = item.get('level') if item else 0
        valid = integer(level) and 0 <= level <= maximum
        if item and integer(item.get('maxLevel')) and item['maxLevel'] < maximum:
            valid = False
        sources[group].append({'name': unit['name'], 'level': level if valid else None,
                               'maximum': maximum, 'unlocked': bool(item)})
    current = maximum = 0
    complete = not unknown
    for group, items in sources.items():
        available = isinstance(profile.get(fields[group]), list)
        if group == 'pets':
            available = available or isinstance(profile.get('pets'), list)
        if fields[group] in unsupported_fields or (group == 'pets' and 'pets' in unsupported_fields):
            available = False
        total = sum(v['maximum'] for v in items)
        valid = available and all(v['level'] is not None for v in items)
        owned = sum(v['level'] or 0 for v in items) if valid else None
        result['groups'][group] = {'current': owned, 'maximum': total, 'percent': round(100 * owned / total, 2) if valid and total else None,
                                   'maxed': sum(v['level'] == v['maximum'] for v in items) if valid else None,
                                   'count': len(items), 'items': items, 'available': valid}
        if not valid and total:
            result['issues'].append('Missing or incompatible ' + group + ' data; no percentage calculated.')
        if group != 'equipment':
            maximum += total
            if valid:
                current += owned
            elif total:
                complete = False
    result.update(current=current if complete else None, maximum=maximum)
    if complete and maximum:
        result['percent'] = round(100 * current / maximum, 2)
    return result


def capture_progression(state):
    state.setdefault('clanHistory', [])
    state.setdefault('memberProgressHistory', {})
    state['progressionInfo'] = {k: v for k, v in PROGRESSION_CAPS.items() if k not in ('units', 'ignored')}
    state['memberProgress'] = {}
    for tag, profile in state.get('profiles', {}).items():
        if not isinstance(profile, dict):
            continue
        progress = army_progress(profile)
        state['memberProgress'][tag] = progress
        if not progress.get('at') or progress.get('percent') is None:
            continue
        sample = {'at': progress['at'], 'townHall': progress['townHall'], 'percent': progress['percent'],
                  'current': progress['current'], 'maximum': progress['maximum'],
                  'groups': {k: {f: v[f] for f in ('current', 'maximum', 'percent')} for k, v in progress['groups'].items()}}
        history = state['memberProgressHistory'].setdefault(tag, [])
        signature = lambda s: (s.get('townHall'), s.get('groups'))
        if not history or signature(history[-1]) != signature(sample):
            state['memberProgressHistory'][tag] = merge_observations(history, [sample])
    observed = api_time(state.get('lastSuccessfulSync'))
    clan = state.get('clanProfile') or {}
    roster = state.get('roster', [])
    if not observed or not clan:
        return
    def total(field):
        return sum(p[field] for p in roster) if all(integer(p.get(field)) for p in roster) else None
    halls = [(p.get('townHallLevel') or (state.get('profiles', {}).get(p.get('tag')) or {}).get('townHallLevel')) for p in roster]
    sample = {'at': observed, 'clanLevel': clan.get('clanLevel'), 'members': len(roster),
              'totalTrophies': total('trophies'), 'seasonDonations': total('donations'),
              'averageTownHall': round(sum(halls) / len(halls), 2) if halls and all(integer(v) for v in halls) else None}
    for field in ('clanPoints', 'clanBuilderBasePoints', 'clanCapitalPoints', 'warWins', 'warWinStreak'):
        sample[field] = clan.get(field) if integer(clan.get(field)) else None
    state['clanHistory'] = merge_observations(state['clanHistory'], [sample], daily=True)


def validate_progress_edits(edits):
    for key, record in edits.get('xpCheckpoints', {}).items():
        if record.get('deleted'):
            continue
        level, xp = record.get('level'), record.get('xp')
        if not api_time(record.get('at')) or not integer(level) or not 1 <= level < len(CLAN_XP_CUMULATIVE):
            raise ValueError('Invalid clan XP checkpoint date or level.')
        limit = CLAN_XP_CUMULATIVE[level] - CLAN_XP_CUMULATIVE[level - 1]
        if not integer(xp) or not 0 <= xp < limit:
            raise ValueError('Clan XP must be the XP within that level, below its next-level requirement.')
    for record in edits.get('villageProgress', {}).values():
        if record.get('deleted'):
            continue
        if not integer(record.get('townHall')) or not 1 <= record['townHall'] <= 99:
            raise ValueError('Invalid manually recorded village Town Hall.')
        for field in ('overall', 'buildings', 'walls'):
            value = record.get(field)
            if value is not None and (isinstance(value, bool) or not isinstance(value, (int, float)) or not 0 <= value <= 100):
                raise ValueError('Manually recorded village percentages must be from 0 to 100.')



